content:
{
  "root_cause": "The GOVUK Tabs component does not recognize the horizontal orientation despite aria-orientation='horizontal' on the tablist, causing ArrowDown to navigate tabs vertically instead of leaving focus on the current tab. The component may require the orientation attribute on the component root element or fail to query the tablist correctly.",
  "repair_strategy": "Add aria-orientation='horizontal' to both the tablist (ul.govuk-tabs__list) and the component root (div#applications-tabs) to ensure the component detects horizontal orientation. Also add role='tablist' to the tablist for proper ARIA structure.",
  "edits": [
    {
      "path": "index.html",
      "sha256": "24e8e15758ccfc9f3b17cadc01108c076cd71ab50482434408642d3a3ece9dfb",
      "before": "  <ul class=\"govuk-tabs__list\">\n    <li class=\"govuk-tabs__list-item govuk-tabs__list-item--selected\"><a class=\"govuk-tabs__tab\" href=\"#past-day\">Past day</a></li>\n    <li class=\"govuk-tabs__list-item\"><a class=\"govuk-tabs__tab\" href=\"#past-week\">Past week</a></li>\n    <li class=\"govuk-tabs__list-item\"><a class=\"govuk-tabs__tab\" href=\"#past-month\">Past month</a></li>\n  </ul>",
      "after": "  <ul class=\"govuk-tabs__list\" role=\"tablist\" aria-orientation=\"horizontal\">\n    <li class=\"govuk-tabs__list-item govuk-tabs__list-item--selected\"><a class=\"govuk-tabs__tab\" href=\"#past-day\">Past day</a></li>\n    <li class=\"govuk-tabs__list-item\"><a class=\"govuk-tabs__tab\" href=\"#past-week\">Past week</a></li>\n    <li class=\"govuk-tabs__list-item\"><a class=\"govuk-tabs__tab\" href=\"#past-month\">Past month</a></li>\n  </ul>"
    },
    {
      "path": "index.html",
      "sha256": "24e8e15758ccfc9f3b17cadc01108c076cd71ab50482434408642d3a3ece9dfb",
      "before": "<div class=\"govuk-tabs\" data-module=\"govuk-tabs\" id=\"applications-tabs\">",
      "after": "<div class=\"govuk-tabs\" data-module=\"govuk-tabs\" id=\"applications-tabs\" aria-orientation=\"horizontal\">"
    }
  ],
  "expected_accessibility_effect": "ArrowDown key press on a focused tab will not change the selected tab or move focus to another tab; only ArrowRight and ArrowLeft will navigate between tabs horizontally. The tab panel remains visible and focus stays on the current tab.",
  "functional_risks": [
    "If the component reads orientation only from the tablist, adding it to the root may have no effect but is harmless.",
    "Duplicate orientation attributes are valid ARIA and should not cause conflicts."
  ],
  "verification_requirements": [
    "Confirm that ArrowDown does not change focus or selected tab when a tab is focused.",
    "Confirm that ArrowRight and ArrowLeft move focus to adjacent tabs as expected.",
    "Verify that the tablist is announced with role tablist and orientation horizontal by assistive technology.",
    "Verify that the component root exposes aria-orientation='horizontal' for any component-level queries."
  ]
}
